const {createApp,nextTick,markRaw}=Vue;
createApp({
 mixins:[RecallWorkbench,RecallAssistant,RecallConversation,RecallVoiceRuntime,RecallQualityView,RecallAdvancedAnalysis],
 data:()=>({dataset:recallDataset,coverage:recallCoverage,domain:'全部',year:'全部',annual:recallAnnual2025,page:2,tabs:['产品批次核验','多维可视化','公告检索','数据与方法','年度分析'],activeSection:'annual-overview',sectionTabs:[[{id:'verify-input',name:'信息填写'},{id:'verify-evidence',name:'核验结果与依据'}],[{id:'analysis-overview',name:'总体概览'},{id:'analysis-risk',name:'类别与风险'},{id:'analysis-time',name:'时间分布'},{id:'analysis-capability',name:'核验能力'},{id:'analysis-risk-composition',name:'风险构成'}],[{id:'search-results',name:'全部公告'},{id:'search-filters',name:'高级筛选'}],[{id:'method-sources',name:'数据来源'},{id:'method-rules',name:'分类与核验规则'},{id:'method-limits',name:'数据边界'},{id:'quality-overview',name:'核验覆盖'},{id:'quality-fields',name:'字段质量'},{id:'quality-records',name:'公告明细'}],[{id:'annual-overview',name:'年度概览'},{id:'annual-months',name:'月度分布'},{id:'annual-records',name:'年度公告目录'}]],annualMonth:'',annualQuery:'',annualStatus:'全部',annualPage:1,annualDetail:null,brand:'罗马仕',model:'PAC20-272',production:'',batch:'',result:null,query:'',category:'全部',risk:'全部',scope:'全部',from:'',to:'',month:'',sort:'new',listPage:1,detail:null,charts:[],matrixMode:'count'}),
 computed:{
  annualRows(){return this.annual.records.filter(r=>(!this.annualMonth||r.published_date.startsWith(this.annualMonth))&&(!this.annualQuery||(r.title+' '+(r.model_raw||'')).toLowerCase().includes(this.annualQuery.toLowerCase()))&&(this.annualStatus==='全部'||r.extraction_status===this.annualStatus))},
  annualPageCount(){return Math.max(1,Math.ceil(this.annualRows.length/8))},
  annualPaged(){return this.annualRows.slice((this.annualPage-1)*8,this.annualPage*8)},
  annualDownloaded(){return this.annual.records.filter(r=>r.sha256).length},
  annualStructured(){return this.annual.records.filter(r=>r.review_status==='已完成AI辅助文本复核').length},
  sampleRange(){const d=this.dataset.map(r=>r.published_date).sort();return d[0]+' — '+d.at(-1)},
  domains(){return ['一般消费品','汽车']},years(){return ['2025','2024','2023']},
  categories(){return RecallAnalysis.counts(this.dataset,'category').map(x=>x[0])},risks(){return RecallAnalysis.counts(this.dataset,'risk_tags').map(x=>x[0])},scopes(){return RecallAnalysis.counts(this.dataset,'scope_assessment').map(x=>x[0])},months(){return RecallAnalysis.months(this.dataset)},
  filtered(){return RecallAnalysis.filter(this.dataset,{domain:this.domain,year:this.year,query:this.query,category:this.category,risk:this.risk,scope:this.scope,from:this.from,to:this.to,month:this.month})},
  sorted(){return [...this.filtered].sort((a,b)=>this.sort==='name'?a.product_name.localeCompare(b.product_name,'zh'):this.sort==='old'?a.published_date.localeCompare(b.published_date):b.published_date.localeCompare(a.published_date))},
  pageCount(){return Math.max(1,Math.ceil(this.sorted.length/8))},paged(){return this.sorted.slice((this.listPage-1)*8,this.listPage*8)},
  uniqueCategories(){return new Set(this.filtered.map(r=>r.category)).size},riskHits(){return this.filtered.reduce((s,r)=>s+r.risk_tags.length,0)},unclearCount(){return this.filtered.filter(r=>r.scope_assessment==='范围细节需补充确认').length},unitTotals(){return RecallAnalysis.units(this.filtered)},missingUnits(){return this.filtered.filter(r=>!r.quantity_unit).length}
 },
 watch:{annualRows(){this.annualPage=1},annualDetail(v){nextTick(()=>{if(v&&!this.$refs.annualDialog.open)this.$refs.annualDialog.showModal();if(!v&&this.$refs.annualDialog.open)this.$refs.annualDialog.close()})},matrixMode(){nextTick(()=>this.draw())},page(){this.activeSection=this.sectionTabs[this.page][0].id;this.dispose();nextTick(()=>{this.draw();window.scrollTo({top:0,behavior:'instant'})})},filtered(){this.listPage=1;nextTick(()=>this.draw())},sort(){this.listPage=1},detail(v){nextTick(()=>{if(v&&!this.$refs.dialog.open)this.$refs.dialog.showModal();if(!v&&this.$refs.dialog.open)this.$refs.dialog.close()})}},
 methods:{
  goSection(id){this.activeSection=id;nextTick(()=>document.getElementById(id)?.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'}))},
  resetFilters(){this.domain='全部';this.year='全部';this.query='';this.category='全部';this.risk='全部';this.scope='全部';this.from='';this.to='';this.month=''},
  toggle(key,value){this[key]=this[key]===value?(key==='month'?'':'全部'):value},
  exportData(){const url=URL.createObjectURL(new Blob([RecallAnalysis.csv(this.sorted)],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='召回公告-筛选结果.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)},
  dispose(){this.charts.forEach(c=>c.dispose());this.charts=[]},
  chart(ref,option){const c=markRaw(echarts.init(this.$refs[ref]));c.setOption({animationDuration:300,textStyle:{fontFamily:'Arial, Microsoft YaHei'},...option});this.charts.push(c);return c},
  draw(){
   if(this.page===3){this.drawQuality();return;}
   if(this.page===4){this.renderReport();return;}
   if(this.page!==1||!this.$refs.matrix)return;this.dispose();
   const selected=this.filtered,cats=RecallAnalysis.counts(selected,'category').map(x=>x[0]),risks=RecallAnalysis.counts(selected,'risk_tags').map(x=>x[0]),months=this.months;
   this.$refs.categoriesChart.style.height=Math.max(320,cats.length*27)+'px';this.$refs.matrix.style.height=Math.max(420,cats.length*30+120)+'px';
   const bar=this.chart('categoriesChart',{tooltip:{trigger:'axis'},grid:{left:110,right:36,top:8,bottom:20},xAxis:{type:'value',minInterval:1,splitLine:{lineStyle:{color:'#eef0ec'}}},yAxis:{type:'category',inverse:true,data:cats,axisTick:{show:false},axisLine:{show:false}},series:[{name:'公告份数',type:'bar',barMaxWidth:15,data:cats.map(c=>({value:selected.filter(n=>n.category===c).length,itemStyle:{color:this.category===c?'#bf8e44':'#547b64'}})),label:{show:true,position:'right'}}]});
   bar.on('click',p=>this.toggle('category',p.name));
   const timeline=this.chart('timeline',{tooltip:{trigger:'axis',formatter:params=>params[0].axisValue+'<br>'+params.map(p=>p.seriesName+'：'+p.value+'份').join('<br>')},dataZoom:[{type:'slider',bottom:30,height:16,start:0,end:100}],legend:{data:['样本背景','当前筛选'],bottom:0},grid:{left:35,right:15,top:12,bottom:105},xAxis:{type:'category',data:months,axisLabel:{rotate:45,fontSize:10},axisLine:{lineStyle:{color:'#cdd7ca'}},axisTick:{show:false}},yAxis:{type:'value',minInterval:1,splitLine:{lineStyle:{color:'#edf0e9'}}},series:[{name:'样本背景',type:'bar',barGap:'-100%',barMaxWidth:20,itemStyle:{color:'#e1e7dc'},data:months.map(m=>this.dataset.filter(r=>r.published_date.startsWith(m)).length)},{name:'当前筛选',type:'bar',barMaxWidth:20,itemStyle:{color:'#537b67'},data:months.map(m=>selected.filter(r=>r.published_date.startsWith(m)).length)}]});
   timeline.on('click',p=>{if(p.value>0)this.toggle('month',p.name)});
   const matrixData=RecallAnalysis.matrix(selected,cats,risks,this.matrixMode==='percent');
   const matrix=this.chart('matrix',{tooltip:{formatter:p=>`${cats[p.value[1]]} · ${risks[p.value[0]]}：${p.value[3]} / ${p.value[4]}份${this.matrixMode==='percent'?' ('+p.value[2]+'%)':''}`},grid:{left:110,right:16,top:12,bottom:105},xAxis:{type:'category',data:risks,axisLabel:{interval:0,rotate:35,fontSize:11},axisLine:{show:false},axisTick:{show:false}},yAxis:{type:'category',inverse:true,data:cats,axisLine:{show:false},axisTick:{show:false}},visualMap:{show:false,min:0,max:this.matrixMode==='percent'?100:Math.max(1,...matrixData.map(d=>d[2])),inRange:{color:['#f1f3ee','#abc4ad','#245c49']}},series:[{type:'heatmap',data:matrixData,label:{show:true,formatter:p=>p.value[3]?(p.value[2]+(this.matrixMode==='percent'?'%':'')):'·'},itemStyle:{borderWidth:3,borderColor:'#fff'}}]});
   matrix.on('click',p=>{if(p.value[2]){const c=cats[p.value[1]],r=risks[p.value[0]];if(this.category===c&&this.risk===r){this.category='全部';this.risk='全部'}else{this.category=c;this.risk=r}}});
   const tree=this.chart('composition',{color:['#416b57','#63866c','#839c77','#a6b790','#bbccad','#9aab91'],tooltip:{formatter:p=>p.name+'：'+p.value+'份，占当前结果 '+(selected.length?(p.value/selected.length*100).toFixed(1):0)+'%'},series:[{type:'treemap',roam:false,nodeClick:false,breadcrumb:{show:false},left:0,right:0,top:0,bottom:0,label:{show:true,formatter:'{b}\n{c} 份',fontSize:12},itemStyle:{borderColor:'#fff',borderWidth:3,gapWidth:3},data:RecallAnalysis.counts(selected,'category').map(([name,value])=>({name,value}))}]});tree.on('click',p=>this.toggle('category',p.name));
   const scope=this.chart('scopeChart',{color:['#547b64','#a9b98e','#c79955','#7d9e9b','#ccd5c0','#8c8170'],tooltip:{trigger:'item',formatter:'{b}：{c}份 ({d}%)'},legend:{bottom:0,textStyle:{fontSize:10},type:'scroll'},series:[{type:'pie',radius:['38%','65%'],center:['50%','43%'],label:{show:false},emphasis:{label:{show:true,fontSize:12}},data:RecallAnalysis.counts(selected,'scope_assessment').map(([name,value])=>({name,value}))}]});scope.on('click',p=>this.toggle('scope',p.name));
   this.drawAdvancedAnalysis();
  }
 },mounted(){nextTick(()=>this.draw());window.addEventListener('resize',()=>this.charts.forEach(c=>c.resize()))}
}).mount('#app');
